<?php
namespace App\Http\Controllers\Api\Accounting;use App\Http\Controllers\Controller;use App\Models\Accounting\RecurringJournal;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class RecurringJournalController extends Controller{public function index(){return response()->json(['success'=>true,'data'=>RecurringJournal::with('lines')->latest()->get()]);}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','frequency'=>'required|in:monthly,quarterly,yearly','next_run'=>'required|date','ends_at'=>'nullable|date','description'=>'nullable|string','lines'=>'required|array|min:2','lines.*.account_id'=>'required|exists:chart_of_accounts,id','lines.*.debit'=>'numeric|min:0','lines.*.credit'=>'numeric|min:0','lines.*.description'=>'nullable|string']);if(round(collect($d['lines'])->sum('debit'),2)!==round(collect($d['lines'])->sum('credit'),2))return response()->json(['message'=>'Debit dan credit harus seimbang.'],422);$j=DB::transaction(function()use($d){$l=$d['lines'];unset($d['lines']);$j=RecurringJournal::create($d);$j->lines()->createMany($l);return $j->load('lines');});return response()->json(['success'=>true,'data'=>$j],201);}}
